<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('pos');
if(!isset($_SESSION['pos_cart']))$_SESSION['pos_cart']=[];$err='';$msg='';
function pos_price(array $p,string $tier):float{if($tier==='offer'&&$p['offer_price']!==null&&$p['offer_price']!=='')return(float)$p['offer_price'];$key=$tier.'_price';return max(0,(float)($p[$key]??$p['retail_price']));}
$customers=db()->query("SELECT id,customer_code,name,mobile,price_tier,state_code,credit_limit FROM customers WHERE active=1 ORDER BY name LIMIT 2000")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='set_customer'){csrf_check();$cid=(int)($_POST['customer_id']??0);if($cid){$st=db()->prepare('SELECT id FROM customers WHERE id=? AND active=1');$st->execute([$cid]);if(!$st->fetchColumn())$cid=0;}$_SESSION['pos_customer_id']=$cid;$_SESSION['pos_tier_override']=null;$msg='Customer updated.';}
$customer=null;$customerId=(int)($_SESSION['pos_customer_id']??0);if($customerId){$st=db()->prepare('SELECT * FROM customers WHERE id=? AND active=1');$st->execute([$customerId]);$customer=$st->fetch();if(!$customer){$customerId=0;$_SESSION['pos_customer_id']=0;}}
$baseTier=$customer['price_tier']??'retail';$tier=$baseTier;
if(is_super_admin()){$postedTier=$_POST['price_tier']??($_SESSION['pos_tier_override']??$baseTier);if(in_array($postedTier,['retail','wholesale','dealer','offer'],true)){$tier=$postedTier;$_SESSION['pos_tier_override']=$tier;}}
else {$_SESSION['pos_tier_override']=null;$tier=$baseTier;}

if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')!=='set_customer'){csrf_check();$action=$_POST['action']??'';
 if($action==='clear'){$_SESSION['pos_cart']=[];$msg='Cart cleared.';}
 if($action==='scan'){$barcode=trim($_POST['barcode']??'');if($barcode==='')$err='Scan a barcode.';else{
  [$scope,$params]=location_scope_sql('ps.location_id');$sql="SELECT ps.id serial_id,ps.serial_barcode,ps.product_id,ps.batch_id,ps.location_id,p.sku,p.product_name,p.color,p.size,p.tax_rate,p.retail_price,p.wholesale_price,p.dealer_price,p.offer_price,b.cost_price,b.batch_no,l.code location_code FROM product_serials ps JOIN products p ON p.id=ps.product_id JOIN batches b ON b.id=ps.batch_id JOIN locations l ON l.id=ps.location_id JOIN inventory_balances ib ON ib.product_id=ps.product_id AND ib.batch_id=ps.batch_id AND ib.location_id=ps.location_id WHERE p.active=1 AND ps.serial_barcode=? AND ps.status='AVAILABLE' AND (ib.qty-ib.reserved_qty)>0".$scope." LIMIT 1";$st=db()->prepare($sql);$st->execute([$barcode,...$params]);$r=$st->fetch();
  if($r){$key='S'.$r['serial_id'];if(isset($_SESSION['pos_cart'][$key]))$err='This unique piece is already in the cart.';else{$_SESSION['pos_cart'][$key]=['serial_id'=>(int)$r['serial_id'],'product_id'=>(int)$r['product_id'],'batch_id'=>(int)$r['batch_id'],'location_id'=>(int)$r['location_id'],'barcode'=>$r['serial_barcode'],'sku'=>$r['sku'],'name'=>$r['product_name'],'variant'=>trim($r['color'].' '.$r['size']),'location'=>$r['location_code'],'qty'=>1,'price'=>pos_price($r,$tier),'tax_rate'=>(float)$r['tax_rate'],'cost'=>(float)$r['cost_price']];$msg='Unique piece added.';}}
  else {
   $st=db()->prepare('SELECT p.serial_tracking FROM products p LEFT JOIN batches b ON b.product_id=p.id WHERE p.product_barcode=? OR b.batch_barcode=? LIMIT 1');$st->execute([$barcode,$barcode]);$serialMode=$st->fetchColumn();if($serialMode!==false&&(int)$serialMode===1){$err='This product uses unique piece barcodes. Scan the individual garment barcode, not the batch/product barcode.';}
   else {[$scope2,$params2]=location_scope_sql('ib.location_id');$sql2="SELECT ib.product_id,ib.batch_id,ib.location_id,ib.qty,ib.reserved_qty,GREATEST(ib.qty-ib.reserved_qty,0) sellable_qty,b.batch_barcode,b.batch_no,b.cost_price,p.sku,p.product_name,p.color,p.size,p.tax_rate,p.retail_price,p.wholesale_price,p.dealer_price,p.offer_price,l.code location_code FROM inventory_balances ib JOIN batches b ON b.id=ib.batch_id JOIN products p ON p.id=ib.product_id JOIN locations l ON l.id=ib.location_id WHERE (ib.qty-ib.reserved_qty)>0 AND p.active=1 AND p.serial_tracking=0 AND (b.batch_barcode=? OR p.product_barcode=?)".$scope2." ORDER BY b.purchased_at,ib.location_id LIMIT 1";$st=db()->prepare($sql2);$st->execute([$barcode,$barcode,...$params2]);$r=$st->fetch();if(!$r)$err='Barcode not found or no available stock in your assigned location.';else{$key='B'.$r['batch_id'].'-'.$r['location_id'];$existing=(float)($_SESSION['pos_cart'][$key]['qty']??0);if($existing+1>(float)$r['sellable_qty'])$err='Insufficient stock.';else{$_SESSION['pos_cart'][$key]=['serial_id'=>null,'product_id'=>(int)$r['product_id'],'batch_id'=>(int)$r['batch_id'],'location_id'=>(int)$r['location_id'],'barcode'=>$r['batch_barcode'],'sku'=>$r['sku'],'name'=>$r['product_name'],'variant'=>trim($r['color'].' '.$r['size']),'location'=>$r['location_code'],'qty'=>$existing+1,'price'=>pos_price($r,$tier),'tax_rate'=>(float)$r['tax_rate'],'cost'=>(float)$r['cost_price']];$msg='Item added.';}}}
  }
 }}
 if($action==='remove'){$key=$_POST['key']??'';unset($_SESSION['pos_cart'][$key]);}
 if($action==='finalize'){$cart=$_SESSION['pos_cart'];if(!$cart)$err='Cart is empty.';else try{
   db()->beginTransaction();
   $customerId=(int)($_SESSION['pos_customer_id']??0);$customer=null;if($customerId){$st=db()->prepare('SELECT * FROM customers WHERE id=? AND active=1 FOR UPDATE');$st->execute([$customerId]);$customer=$st->fetch();if(!$customer)throw new Exception('Selected customer is not active.');}
   $baseTier=$customer['price_tier']??'retail';$finalTier=$baseTier;if(is_super_admin()){$_t=$_POST['price_tier']??($_SESSION['pos_tier_override']??$baseTier);if(in_array($_t,['retail','wholesale','dealer','offer'],true))$finalTier=$_t;}
   $locked=[];$subtotal=0.0;
   foreach($cart as $key=>$item){
    $st=db()->prepare('SELECT ib.qty,ib.reserved_qty,p.sku,p.product_name,p.tax_rate,p.retail_price,p.wholesale_price,p.dealer_price,p.offer_price,p.serial_tracking,b.cost_price FROM inventory_balances ib JOIN products p ON p.id=ib.product_id JOIN batches b ON b.id=ib.batch_id WHERE p.active=1 AND ib.product_id=? AND ib.batch_id=? AND ib.location_id=? FOR UPDATE');$st->execute([$item['product_id'],$item['batch_id'],$item['location_id']]);$r=$st->fetch();if(!$r)throw new Exception('Stock record missing for '.$item['sku']);$qty=(float)$item['qty'];if(((float)$r['qty']-(float)$r['reserved_qty'])<$qty)throw new Exception('Sellable stock changed or is reserved for an online order: '.$item['sku']);
    $serialId=$item['serial_id']??null;if($serialId){$ss=db()->prepare("SELECT * FROM product_serials WHERE id=? FOR UPDATE");$ss->execute([(int)$serialId]);$sr=$ss->fetch();if(!$sr||$sr['status']!=='AVAILABLE'||(int)$sr['product_id']!==(int)$item['product_id']||(int)$sr['batch_id']!==(int)$item['batch_id']||(int)$sr['location_id']!==(int)$item['location_id'])throw new Exception('Unique barcode is no longer available: '.$item['barcode']);$qty=1;}
    elseif((int)$r['serial_tracking']===1)throw new Exception('Serialized product requires individual barcode.');
    $price=pos_price($r,$finalTier);$line=round($qty*$price,2);$subtotal+=$line;$locked[$key]=$item+['qty'=>$qty,'price'=>$price,'line_total'=>$line,'tax_rate'=>(float)$r['tax_rate'],'cost'=>(float)$r['cost_price']];
   }
   $subtotal=round($subtotal,2);$discount=max(0,round((float)($_POST['discount']??0),2));$capPct=user_discount_cap_pct();$maxDiscount=round($subtotal*$capPct/100,2);if($discount>$maxDiscount+0.001)throw new Exception('Discount exceeds your allowed limit of '.number_format($capPct,2).'%.');if($discount>$subtotal+0.001)throw new Exception('Discount cannot exceed taxable subtotal.');
   $taxTotal=0.0;$allocated=0.0;$n=count($locked);$ix=0;foreach($locked as $key=>&$item){$ix++;$share=($ix===$n)?round($discount-$allocated,2):round($subtotal>0?$discount*($item['line_total']/$subtotal):0,2);$share=max(0,min($share,$item['line_total']));$allocated+=$share;$taxable=round($item['line_total']-$share,2);$taxAmount=round($taxable*$item['tax_rate']/100,2);$item['discount_share']=$share;$item['taxable_value']=$taxable;$item['tax_amount']=$taxAmount;$taxTotal+=$taxAmount;}unset($item);$taxTotal=round($taxTotal,2);$grand=round(max(0,$subtotal-$discount+$taxTotal),2);
   $payMode=$_POST['payment_mode']??'CASH';if(!in_array($payMode,['CASH','CARD','UPI','CREDIT','MIXED'],true))$payMode='CASH';$cash=$card=$upi=$credit=0.0;if($payMode==='CASH')$cash=$grand;elseif($payMode==='CARD')$card=$grand;elseif($payMode==='UPI')$upi=$grand;elseif($payMode==='CREDIT')$credit=$grand;else{$cash=max(0,(float)($_POST['cash_amount']??0));$card=max(0,(float)($_POST['card_amount']??0));$upi=max(0,(float)($_POST['upi_amount']??0));$credit=max(0,(float)($_POST['credit_amount']??0));if(abs(($cash+$card+$upi+$credit)-$grand)>0.02)throw new Exception('Mixed payment amounts must exactly match the bill total.');}
   if($credit>0&&!$customer)throw new Exception('Credit sale requires a selected customer.');if($customer&&$credit>0){$st=db()->prepare('SELECT COALESCE(SUM(debit-credit),0) FROM customer_ledger WHERE customer_id=?');$st->execute([$customer['id']]);$out=(float)$st->fetchColumn();$limit=(float)$customer['credit_limit'];if($limit>0&&$out+$credit>$limit+0.01&&!is_super_admin())throw new Exception('Customer credit limit exceeded.');}
   $companyState=trim((string)(setting('company_state_code','')??''));if($taxTotal>0&&$companyState==='')throw new Exception('Set Company State Code in Settings before GST billing.');$posState=trim((string)($customer['state_code']??($_POST['place_of_supply']??$companyState)));if($posState==='')$posState=$companyState;if($posState!==''&&!preg_match('/^\d{2}$/',$posState))throw new Exception('Place of Supply State Code must be exactly 2 digits.');$gstType=($companyState!==''&&$posState!==''&&$companyState!==$posState)?'IGST':'CGST_SGST';$prefix=preg_replace('/[^A-Z0-9-]/i','',setting('invoice_prefix','PF')??'PF');if($prefix==='')$prefix='PF';$invoice=$prefix.'-'.date('Ymd-His').'-'.random_int(100,999);
   $paid=round($cash+$card+$upi,2);$st=db()->prepare('INSERT INTO sales(invoice_no,customer_id,customer_name,customer_mobile,price_tier,subtotal,tax_total,discount_total,grand_total,payment_mode,paid_total,credit_total,place_of_supply,gst_type,cashier_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$invoice,$customer['id']??null,$customer['name']??trim($_POST['customer_name']??''),$customer['mobile']??trim($_POST['customer_mobile']??''),$finalTier,$subtotal,$taxTotal,$discount,$grand,$payMode,$paid,$credit,$posState,$gstType,current_user()['id']]);$saleId=(int)db()->lastInsertId();
   $si=db()->prepare('INSERT INTO sale_items(sale_id,product_id,batch_id,location_id,barcode,serial_id,quantity,unit_price,tax_rate,line_total,discount_share,taxable_value,tax_amount,cost_snapshot) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$upd=db()->prepare('UPDATE inventory_balances SET qty=qty-? WHERE product_id=? AND batch_id=? AND location_id=?');$ub=db()->prepare('UPDATE batches SET qty_available=qty_available-? WHERE id=?');$sl=db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_out,reference_type,reference_id,unit_rate,remarks,created_by) VALUES('SALE',?,?,?,?, 'SALE',?,?,?,?)");
   foreach($locked as $item){$si->execute([$saleId,$item['product_id'],$item['batch_id'],$item['location_id'],$item['barcode'],$item['serial_id'],$item['qty'],$item['price'],$item['tax_rate'],$item['line_total'],$item['discount_share'],$item['taxable_value'],$item['tax_amount'],$item['cost']]);$upd->execute([$item['qty'],$item['product_id'],$item['batch_id'],$item['location_id']]);$ub->execute([$item['qty'],$item['batch_id']]);if($item['serial_id']){$serialUpd=db()->prepare("UPDATE product_serials SET status='SOLD' WHERE id=? AND status='AVAILABLE'");$serialUpd->execute([(int)$item['serial_id']]);if($serialUpd->rowCount()!==1)throw new Exception('Unique barcode status changed during billing.');}$sl->execute([$item['product_id'],$item['batch_id'],$item['location_id'],$item['qty'],$saleId,$item['price'],$invoice,current_user()['id']]);maybe_publish_low_stock((int)$item['product_id'],(int)$item['location_id']);}
   $paySt=db()->prepare('INSERT INTO sale_payments(sale_id,mode,amount,reference_no) VALUES(?,?,?,?)');if($cash>0)$paySt->execute([$saleId,'CASH',$cash,null]);if($upi>0)$paySt->execute([$saleId,'UPI',$upi,trim($_POST['upi_ref']??'')]);if($card>0)$paySt->execute([$saleId,'CARD',$card,trim($_POST['card_ref']??'')]);if($credit>0)$paySt->execute([$saleId,'CREDIT',$credit,null]);if($credit>0&&$customer)db()->prepare("INSERT INTO customer_ledger(customer_id,txn_type,debit,reference_type,reference_id,remarks,created_by) VALUES(?,'SALE_CREDIT',?,'SALE',?,?,?)")->execute([$customer['id'],$credit,$saleId,$invoice,current_user()['id']]);
   db()->commit();audit('SALE_FINALIZE','sale',$saleId,['invoice'=>$invoice,'total'=>$grand,'payment_mode'=>$payMode]);publish_event('SALE_FINALIZED','Sale completed',$invoice.' · ₹'.number_format($grand,2),['super_admin'],'sale',$saleId,null);publish_scoped_event('SALE_STOCK_OUT','Sale stock issued',$invoice.' · stock deducted',['manager','godown'],'sale',$saleId);$_SESSION['pos_cart']=[];$_SESSION['pos_customer_id']=0;$_SESSION['pos_tier_override']=null;redirect('invoice.php?id='.$saleId);
  }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err='Billing failed: '.$e->getMessage();}}
}
$customerId=(int)($_SESSION['pos_customer_id']??0);$customer=null;if($customerId){$st=db()->prepare('SELECT * FROM customers WHERE id=? AND active=1');$st->execute([$customerId]);$customer=$st->fetch();}$baseTier=$customer['price_tier']??'retail';if(!is_super_admin())$tier=$baseTier;
$subtotal=0;$tax=0;foreach($_SESSION['pos_cart'] as $i){$line=$i['qty']*$i['price'];$subtotal+=$line;$tax+=$line*$i['tax_rate']/100;}$gross=$subtotal+$tax;$cap=user_discount_cap_pct();page_header('POS Billing · Barcode Scan');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
